export function existsInGrid(board, word) {
    if (!word)
        return true;
    const rows = board.length, cols = rows ? board[0].length : 0, visited = new Set();
    function dfs(r, c, i) {
        if (i === word.length)
            return true;
        if (r < 0 || c < 0 || r >= rows || c >= cols || board[r][c] !== word[i] || visited.has(r * cols + c))
            return false;
        const k = r * cols + c;
        visited.add(k);
        const ok = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) || dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);
        visited.delete(k);
        return ok;
    }
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (dfs(r, c, 0))
                return true;
    return false;
}
